"use client";
import React, { useState } from "react";
import postSubscribe from "@/services/subscribe";
import Destinations from "../destinations";
import BlogTeasers from "../blog-teasers";

const visaFaqs = [
  {
    q: "What does a visa mean?",
    a: "A visa is a government-issued document that permits legal entry into another country. Various types of visas grant different privileges and usually have distinct application procedures and fees. Typically, visas are valid for a limited duration.",
  },
  {
    q: "What does a tourist visa allow?",
    a: "Tourist visas (or travel visas) permit entry into a foreign country for leisure and sightseeing activities, with a set duration of stay. This is typically the type of visa needed for most trips with TravelShop Booking. These visas do not authorize work or business activities in the destination country.",
  },
  {
    q: "What does an eVisa provide?",
    a: "An eVisa (electronic visa) is a digital visa linked to your passport number, rather than being physically stamped in your passport. Travelers with an eVisa should print the confirmation document and keep it with them during their journey.",
  },
  {
    q: "Why is a visa necessary?",
    a: "Visas allow countries to monitor entries and exits. Whether you need one depends on your nationality and destination. If there is no visa agreement between your home country and the country you plan to visit, you'll need to apply for a visa in advance.",
  },
  {
    q: "What does an invitation letter involve?",
    a: "An Invitation Letter is a formal document sometimes required by countries with strict visa policies. It's issued by the person(s) you plan to visit, confirming they are inviting you. For certain TravelShop Booking trips, your tour operator may assist in providing this letter if necessary.",
  },
  {
    q: "What is the processing time for a visa?",
    a: "Visa processing times vary by country. Visit the government website of your destination to learn about their processing speed. Some countries may take up to 8 weeks, while others could process visas in as little as 1 to 15 days.",
  },
];

const keyPoints = [
  "It is highly advised to give yourself ample time for visa processing before your trip.",
  "It's advised to work directly with your local embassy or authorized agents.",
  "Embassies often require full payment for tours and confirmation of entry and exit (flights to and from the country) before you can submit a visa application.",
  "Visa regulations can change, so always verify the latest information with the embassy in your country.",
  "Obtaining a visa is the sole responsibility of the traveler.",
  "TravelShop Booking is not liable for sudden changes in visa application processes or if a traveler's visa is denied or expires.",
];

const Visa = () => {
  const [subscribeLoading, setSubscribeLoading] = useState(false);
  const [subscribeMail, setSubscribeMail] = useState("");
  const [subscribeStatus, setSubscribeStatus] = useState("");
  const [subscribeErrorMessage, setSubscribeErrorMessage] = useState("");
  const isEmail = (email: string) =>
    /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i.test(email);

  const subscribePost = async () => {
    if (!subscribeMail || !isEmail(subscribeMail)) {
      setSubscribeErrorMessage("Please specify a valid email address");
      setSubscribeStatus("error");
    } else {
      setSubscribeLoading(true);
      setSubscribeStatus("");
      await postSubscribe(subscribeMail).then(() => {
        setSubscribeMail("");
        setSubscribeStatus("success");
        setSubscribeLoading(false);
      });
    }
  };

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/sahara.png')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.45) 0%, rgba(20,16,28,0.6) 55%, rgba(20,16,28,0.82) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Visa Assistance
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Obtain Your e-Visa
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Ready for your trip and looking to simplify travel formalities?
              We&apos;ve teamed up with Sherpa to help you quickly obtain your
              e-Visa directly through TravelShop Booking.
            </p>
          </div>
        </div>
      </section>

      {/* Visa guide */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Visas: A Complete Guide
            </h2>
            <p className="tw-mt-1.5 tw-mb-0 tw-text-sm tw-text-[#6b6577]">
              Everything you need to know before you apply.
            </p>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {visaFaqs.map((item) => (
              <div
                key={item.q}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
              >
                <h3 className="tw-text-[17px] tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-3">
                  {item.q}
                </h3>
                <p className="tw-m-0 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
                  {item.a}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Key points */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Before you apply
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Important Points to Consider
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                When organizing an international trip, finding reliable visa
                information can seem challenging. Having a dependable resource
                to guide you through the process is crucial. Here are some key
                points to keep in mind when applying for a visa:
              </p>
              <ul className="tw-mt-5 tw-space-y-3 tw-p-0 tw-m-0 tw-list-none">
                {keyPoints.map((point) => (
                  <li
                    key={point}
                    className="tw-flex tw-gap-3 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]"
                  >
                    <svg
                      viewBox="0 0 512 512"
                      width={20}
                      height={20}
                      fill="currentColor"
                      aria-hidden="true"
                      className="tw-mt-0.5 tw-shrink-0 tw-text-[#854ec9]"
                    >
                      <path d="M256 512A256 256 0 1 0 256 0a256 256 0 1 0 0 512zM369 209L241 337c-9.4 9.4-24.6 9.4-33.9 0l-64-64c-9.4-9.4-9.4-24.6 0-33.9s24.6-9.4 33.9 0l47 47L335 175c9.4-9.4 24.6-9.4 33.9 0s9.4 24.6 0 33.9z" />
                    </svg>
                    <span>{point}</span>
                  </li>
                ))}
              </ul>
            </div>
            <div>
              <img
                src="/images/plan.avif"
                alt="Plan your visa"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      <BlogTeasers />

      {/* Newsletter */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-relative tw-overflow-hidden tw-rounded-3xl tw-px-7 tw-py-12 md:tw-px-12 md:tw-py-14">
            <div
              className="tw-absolute tw-inset-0"
              style={{
                background:
                  "linear-gradient(120deg, #854ec9 0%, #6a3da4 60%, #4f2d7f 100%)",
              }}
              aria-hidden="true"
            />
            <div className="tw-relative tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-8 tw-items-center">
              <div>
                <h2 className="tw-text-[clamp(22px,3vw,30px)] tw-font-bold tw-tracking-tight tw-text-white tw-m-0">
                  Subscribe to Our Newsletter
                </h2>
                <p className="tw-mt-3 tw-mb-0 tw-text-[15px] tw-leading-[1.6] tw-text-white/85">
                  Enjoy savings of up to 50% on our tours! Gain exclusive access
                  to email-only offers for members.
                </p>
              </div>
              <div>
                {subscribeStatus === "error" && (
                  <div className="tw-mb-3 tw-rounded-xl tw-bg-white/15 tw-border tw-border-solid tw-border-white/30 tw-px-4 tw-py-3 tw-text-[14px] tw-font-medium tw-text-white">
                    {subscribeErrorMessage}
                  </div>
                )}
                {subscribeStatus === "success" && (
                  <div className="tw-mb-3 tw-rounded-xl tw-bg-white/15 tw-border tw-border-solid tw-border-white/30 tw-px-4 tw-py-3 tw-text-[14px] tw-font-medium tw-text-white">
                    Your registration has been received. We thank you.
                  </div>
                )}
                <div className="tw-flex tw-flex-col sm:tw-flex-row tw-gap-2.5">
                  <input
                    type="email"
                    id="visa-subscribe-mail-input"
                    placeholder="Your email"
                    aria-label="Your email"
                    value={subscribeMail}
                    onChange={(e) => setSubscribeMail(e.target.value)}
                    className="tw-flex-1 tw-rounded-full tw-border tw-border-solid tw-border-white/30 tw-bg-white/95 tw-px-5 tw-py-3 tw-text-[15px] tw-text-[#14101c] tw-outline-none focus:tw-ring-2 focus:tw-ring-white/60"
                  />
                  <button
                    type="button"
                    disabled={subscribeLoading}
                    onClick={subscribePost}
                    className="tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-bg-white hover:tw-bg-[#f3f1f7] disabled:tw-opacity-70 tw-text-[#854ec9] tw-font-semibold tw-text-[15px] tw-px-7 tw-py-3 tw-rounded-full tw-transition-colors"
                  >
                    {subscribeLoading ? "Loading..." : "Subscribe"}
                  </button>
                </div>
                <p className="tw-mt-3 tw-mb-0 tw-text-[12px] tw-leading-[1.5] tw-text-white/75">
                  By submitting this form, I agree to the TravelShop Booking{" "}
                  <a
                    href="/terms-of-use"
                    className="tw-font-semibold tw-text-white"
                  >
                    Terms of Use
                  </a>{" "}
                  and{" "}
                  <a
                    href="/privacy-policy"
                    className="tw-font-semibold tw-text-white"
                  >
                    Privacy Policy
                  </a>
                  .
                </p>
              </div>
            </div>
          </div>
        </div>
      </section>

      <Destinations />
    </main>
  );
};

export default Visa;
